css:
.sl-testimonial-grid {
    padding: clamp(3rem, 6vw, 5rem) clamp(1rem, 4vw, 2rem);
    width: 100%;
    background-color: var(--smartlearn-bg);
    font-family: var(--smartlearn-body-font, system-ui, sans-serif);
}

.sl-testimonial-grid .sl-container {
    max-width: 1200px;
    margin: 0 auto;
}

.sl-testimonial-grid .sl-header {
    text-align: center;
    margin-bottom: 4rem;
}

.sl-testimonial-grid .sl-title {
    font-family: var(--smartlearn-heading-font, system-ui, sans-serif);
    font-size: clamp(1.75rem, 3.5vw, 2.5rem);
    font-weight: 800;
    color: var(--smartlearn-text);
    margin-bottom: 1rem;
}

.sl-testimonial-grid .sl-subtitle {
    font-size: 1.125rem;
    color: var(--smartlearn-text-muted);
}

.sl-testimonial-grid .sl-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(min(100%, 280px), 1fr));
    gap: 2rem;
}

.sl-testimonial-grid .sl-card {
    margin: 0;
    background: var(--smartlearn-card-bg);
    border: 1px solid var(--smartlearn-card-border, rgba(0, 0, 0, 0.1));
    border-radius: var(--smartlearn-radius, 12px);
    padding: 2.5rem;
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    display: flex;
    flex-direction: column;
    justify-content: space-between;
}

.sl-testimonial-grid .sl-blockquote {
    margin: 0;
}

.sl-testimonial-grid .sl-quote {
    font-size: 1.125rem;
    color: var(--smartlearn-text);
    line-height: 1.6;
    font-style: italic;
    margin-bottom: 2rem;
}

.sl-testimonial-grid .sl-author {
    display: flex;
    align-items: center;
    gap: 1rem;
}

.sl-testimonial-grid .sl-avatar {
    width: 50px;
    height: 50px;
    border-radius: 50%;
    object-fit: cover;
    object-position: center top;
    flex-shrink: 0;
}

.sl-testimonial-grid .sl-name {
    font-weight: 700;
    color: var(--smartlearn-text);
    font-size: 1rem;
}

.sl-testimonial-grid .sl-role {
    color: var(--smartlearn-text-muted);
    font-size: 0.875rem;
}
